.fb-book{position:relative;margin:0 auto;width:min(100%,calc((100dvh - 230px) * var(--fb-ratio)));perspective:2400px;cursor:pointer;user-select:none;touch-action:pan-y;background:radial-gradient(ellipse at center,#00000014,transparent 70%)}
.fb-book:focus-visible{outline:3px solid #2476a8;outline-offset:4px}
.fb-face{position:absolute;top:0;height:100%;width:50%;background:#fff;overflow:hidden;display:flex;align-items:center;justify-content:center}
.fb-face img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none}
.fb-left{left:0;box-shadow:-6px 6px 18px #0003;border-radius:3px 0 0 3px}
.fb-right{left:50%;box-shadow:6px 6px 18px #0003;border-radius:0 3px 3px 0}
.fb-empty{background:transparent;box-shadow:none}
.fb-paper{background:#f7f5f0}
.fb-single{left:0;width:100%;box-shadow:0 6px 18px #0003}
.fb-loading{font-size:13px;color:#617381}
.fb-spine{position:absolute;top:0;bottom:0;left:calc(50% - 14px);width:28px;pointer-events:none;background:linear-gradient(90deg,transparent,#0000001f 45%,#00000033 50%,#0000001f 55%,transparent)}
.fb-leaf{position:absolute;top:0;height:100%;width:50%;transform-style:preserve-3d;transition:transform .64s cubic-bezier(.45,.05,.3,1);z-index:3}
.fb-leaf .fb-face{left:0;width:100%;backface-visibility:hidden;-webkit-backface-visibility:hidden}
.fb-leaf .fb-back{transform:rotateY(180deg)}
.fb-leaf-right{left:50%;transform-origin:left center}
.fb-leaf-right.is-turning{transform:rotateY(-180deg)}
.fb-leaf-left{left:0;transform-origin:right center}
.fb-leaf-left.is-turning{transform:rotateY(180deg)}
.fb-leaf-single{left:0;width:100%;transform-origin:left center}
.fb-leaf-single.is-turning{transform:rotateY(-180deg)}
.fb-leaf-single.is-reverse{transform:rotateY(-180deg)}
.fb-leaf-single.is-reverse.is-turning{transform:rotateY(0)}
.fb-leaf .fb-front:after,.fb-leaf .fb-back:after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#0000,#0000 60%,#0000001a)}
.fb-hint{margin:0;text-align:center;font-size:12px;color:#617381}
@media (prefers-reduced-motion:reduce){.fb-leaf{transition-duration:.01s}}
